      "id": "a1-aus",
      "layout": "standardStudy",
      "translation": "ulos • kotoisin",
      "explanation": [
        "Perusajatus: aus tarkoittaa ’jostakin, ulos jostakin’ (sisältä) ja ilmaisee alkuperää, materiaalia tai syytä: aus dem Haus (ulos talosta), aus Lettland (Latviasta), aus Holz (puusta).",
        "Preposition jälkeen tulee aina datiivi: aus dem Haus, aus der Stadt, aus einem Buch.",
        "Syyn merkityksessä aus ilmaisee tunneperäistä vaikutinta: aus Angst (pelosta), aus Liebe (rakkaudesta)."
      ],
      "examples": [
        {
          "de": "Ich komme aus Lettland.",
          "lv": "Olen kotoisin Latviasta."
        },
        {
          "de": "Er nimmt ein Heft aus der Tasche.",
          "lv": "Hän ottaa vihon laukusta."
        },
        {
          "de": "Der Tisch ist aus Holz.",
          "lv": "Pöytä on tehty puusta."
        },
        {
          "de": "Sie schweigt aus Angst.",
          "lv": "Hän on hiljaa pelosta."
        },
        {
          "de": "Der Zug aus Berlin hat Verspätung.",
          "lv": "Berliinistä tuleva juna on myöhässä."
        }
      ],
      "comparison": [
        {
          "word": "von",
          "meaning": "jostakin, joltakin (ihmiseltä, lähtökohdasta)",
          "example": "Ich habe einen Brief von meiner Mutter. – Minulla on kirje äidiltäni."
        },
        {
          "word": "bei",
          "meaning": "luona",
          "example": "Ich bin bei meiner Oma. – Olen mummini luona."
        },
        {
          "word": "nach",
          "meaning": "johonkin (kaupunkiin)",
          "example": "Ich fahre nach Berlin. – Matkustan Berliiniin."
        }
      ],
      "tip": [
        "Aus = ’ulos jostakin sisältä’: Auto, Haus, Tasche. Vastakohta on in.",
        "Kun kerrotaan, mistä maasta tai kaupungista joku on kotoisin, käytetään aus: Ich bin aus Riga."
      ],
      "important": [
        "Aus-sanan jälkeen tulee aina datiivi, ei koskaan akkusatiivi.",
        "Ihminen, jolta jotakin saadaan, ilmaistaan von-prepositiolla: ein Brief von Anna, ei ’aus Anna’."
      ],
