        "Se taipuu kuten määräinen artikkeli der: nominatiivi dieser/diese/dieses, akkusatiivi diesen (maskuliini), datiivi diesem/dieser/diesem. Monikossa: diese, diesen. Neutrimuoto dieses Jahr tarkoittaa ’tänä vuonna’.",
