      "id": "a1-frau",
      "layout": "standardStudy",
      "translation": "nainen • vaimo",
      "explanation": [
        "Perusajatus: die Frau on feminiininen substantiivi, jonka merkityksiä ovat nainen, rouva (Frau Schmidt) ja vaimo (meine Frau). Monikko on die Frauen.",
        "Sukunimen edellä Frau tarkoittaa ’rouva’: Guten Tag, Frau Berger! Ilmaus meine Frau tarkoittaa yleensä ’vaimoni’, kun puhutaan perheestä.",
        "Yksikössä sana Frau ei itse muutu, vain artikkeli muuttuu: die Frau, der Frau."
      ],
      "examples": [
        {
          "de": "Die Frau dort ist meine Lehrerin.",
          "lv": "Tuo nainen tuolla on opettajani."
        },
        {
          "de": "Frau Schmidt ist Ärztin.",
          "lv": "Rouva Schmidt on lääkäri."
        },
        {
          "de": "Meine Frau arbeitet in Riga.",
          "lv": "Vaimoni on töissä Riiassa."
        },
        {
          "de": "Zwei Frauen warten vor dem Haus.",
          "lv": "Kaksi naista odottaa talon edessä."
        },
        {
          "de": "Guten Tag, Frau Berger!",
          "lv": "Hyvää päivää, rouva Berger!"
        }
      ],
      "comparison": [
        {
          "word": "der Mann",
          "meaning": "mies",
          "example": "Der Mann liest. – Mies lukee."
        },
        {
          "word": "die Dame",
          "meaning": "rouva, nainen (kohtelias sana)",
          "example": "Die Dame wartet. – Rouva odottaa."
        },
        {
          "word": "das Mädchen",
          "meaning": "tyttö",
          "example": "Das Mädchen lacht. – Tyttö nauraa."
        }
      ],
      "tip": [
        "Kohteliaassa puhuttelussa käytetään Frau + sukunimi, ei pelkkää etunimeä.",
        "Die Frau, die Frauen — monikko päätteellä -en."
      ],
      "important": [
        "Frau sukunimen edellä ei tarkoita ’naimisissa olevaa’, se on kohteliaisuusmuoto.",
        "Fräulein on vanhentunut; nykyään puhutellaan sanalla Frau."
      ],
