      "explanation": [
        "Perusajatus: geben tarkoittaa ’antaa’ jollekulle jotakin. Tyypillinen rakenne: jemandem (datiivi, kenelle?) etwas (akkusatiivi, mitä?): Ich gebe dir das Buch.",
        "Muodot: du gibst, er gibt (e → i), gab, hat gegeben. Ilmaus es gibt + akkusatiivi tarkoittaa ’on, on olemassa’: Es gibt hier ein Café.",
        "Samoin: eine Antwort geben (vastata), Hausaufgaben geben (antaa läksyjä), die Hand geben (kätellä)."
      ],
      "examples": [
        {
          "de": "Ich gebe dir das Buch.",
          "lv": "Annan sinulle kirjan."
        },
        {
          "de": "Gibst du mir bitte den Zucker?",
          "lv": "Ojentaisitko minulle sokerin?"
        },
        {
          "de": "Es gibt hier viele Restaurants.",
          "lv": "Täällä on paljon ravintoloita."
        },
        {
          "de": "Der Lehrer gibt den Kindern Hausaufgaben.",
          "lv": "Opettaja antaa lapsille läksyjä."
        },
        {
          "de": "Was gibt es heute zum Essen?",
          "lv": "Mitä tänään syödään?"
        }
      ],
      "comparison": [
        {
          "word": "schenken",
          "meaning": "lahjoittaa, antaa lahjaksi",
          "example": "Er schenkt ihr Blumen. – Hän antaa hänelle kukkia lahjaksi."
        },
        {
          "word": "nehmen",
          "meaning": "ottaa",
          "example": "Ich nehme den Kaffee. – Otan kahvin."
        },
        {
          "word": "bekommen",
          "meaning": "saada",
          "example": "Ich bekomme ein Geschenk. – Saan lahjan."
        }
      ],
      "tip": [
        "Laita ensin ihminen datiivissa, sitten asia akkusatiivissa: Ich gebe dem Kind einen Apfel.",
        "Es gibt -ilmauksen kanssa on aina akkusatiivi: Es gibt einen Park."
      ],
      "important": [
        "Yksikön kolmannessa persoonassa on er gibt (ei ’er gebt’); gebt on ihr-muoto.",
        "Es gibt ei tarkoita ’se antaa’: se on kiinteä fraasi, jonka merkitys on ’on olemassa’."
      ],
