      "translation": "pitää • pysähtyä",
      "explanation": [
        "Perusajatus: halten tarkoittaa pitää kädessä tai pidellä: Sie hält ein Baby im Arm. Sillä on myös merkitykset pysähtyä (Der Zug hält), pitää jonakin (etwas für gut halten) ja pitää puhe (eine Rede halten).",
        "Muodot: du hältst, er hält (a → ä), hielt, hat gehalten. Pitää jonakin: jemanden/etwas für + akkusatiivi halten.",
        "Halt! käskynä tarkoittaa 'seis!', mutta Halt die Tür! — 'Pidä ovea!'."
      ],
      "examples": [
        {
          "de": "Sie hält ein Baby im Arm.",
          "lv": "Hän pitää vauvaa sylissään."
        },
        {
          "de": "Der Zug hält in Hamburg.",
          "lv": "Juna pysähtyy Hampurissa."
        },
        {
          "de": "Ich halte das für eine gute Idee.",
          "lv": "Pidän sitä hyvänä ideana."
        },
        {
          "de": "Er hält eine Rede.",
          "lv": "Hän pitää puheen."
        },
        {
          "de": "Halt bitte die Tür!",
          "lv": "Pidä ovea auki, ole hyvä!"
        }
      ],
