        "Käyttö: in den Laden gehen (mennä kauppaan), im Laden einkaufen. Yhdyssanoissa: Blumenladen (kukkakauppa), Bioladen, Schreibwarenladen. Isoa kauppaa sanotaan nimellä Supermarkt.",
