      "explanation": [
        "Perusajatus: sagen tarkoittaa ”sanoa, lausua”, kun joku ilmaisee sanoja tai mielipiteen: Was hast du gesagt? Er sagt die Wahrheit. Wie sagt man das auf Deutsch?",
        "Taivutusmuodot: sagt, sagte, hat gesagt. Henkilö, jolle sanotaan, on datiivissa, sanottu asia akkusatiivissa: Ich sage dir die Wahrheit. Usein dass-sivulauseen kanssa: Sie sagt, dass sie müde ist.",
        "Suorassa esityksessä: Er sagt: „Ich komme.“ Ero verbiin sprechen: sagen — sanoa tietty sisältö, sprechen — puhua (kieltä, jonkun kanssa)."
      ],
      "examples": [
        {
          "de": "Was hast du gesagt?",
          "lv": "Mitä sinä sanoit?"
        },
        {
          "de": "Er sagt immer die Wahrheit.",
          "lv": "Hän sanoo aina totuuden."
        },
        {
          "de": "Wie sagt man das auf Deutsch?",
          "lv": "Miten se sanotaan saksaksi?"
        },
        {
          "de": "Sag mir bitte deinen Namen!",
          "lv": "Sano minulle nimesi, ole hyvä!"
        },
        {
          "de": "Sie sagt, dass sie müde ist.",
          "lv": "Hän sanoo olevansa väsynyt."
        }
      ],
      "comparison": [
        {
          "word": "sprechen",
          "meaning": "puhua",
          "example": "Ich spreche Deutsch. – Puhun saksaa."
        },
        {
          "word": "erzählen",
          "meaning": "kertoa",
          "example": "Er erzählt eine Geschichte. – Hän kertoo tarinan."
        },
        {
          "word": "meinen",
          "meaning": "tarkoittaa, olla mieltä",
          "example": "Was meinst du? – Mitä mieltä olet?"
        }
      ],
      "tip": [
        "Sagen + datiivi (kenelle?) + akkusatiivi (mitä?): Ich sage dir etwas.",
        "Sagen-verbiä seuraa usein dass-sivulause tai suora esitys."
      ],
      "important": [
        "Älä sekoita verbejä sagen (sanoa) ja sprechen (puhua kieltä tai jonkun kanssa): Ich spreche Deutsch, ei ”Ich sage Deutsch”.",
        "Sagen on säännöllinen: sagte, gesagt."
      ],
