      "id": "a1-fernsehen",
      "layout": "standardStudy",
      "translation": "katsoa televisiota",
      "explanation": [
        "Perusajatus: fernsehen on erotettava verbi: ich sehe fern, du siehst fern, er sieht fern; preteriti sah fern, perfekti hat ferngesehen. Zu-infinitiivi: fernzusehen.",
        "Lauseessa fern on lopussa: Ich sehe abends fern. Se tarkoittaa katsoa televisiota tai televisio-ohjelmia, yleensä ilman objektia.",
        "Tiettyä elokuvaa tai ohjelmaa katsotaan yleensä verbillä ansehen: Wir sehen uns einen Film an."
      ],
      "examples": [
        {
          "de": "Ich sehe abends gern fern.",
          "lv": "Katson iltaisin mielelläni televisiota."
        },
        {
          "de": "Die Kinder sehen jeden Tag eine Stunde fern.",
          "lv": "Lapset katsovat televisiota tunnin joka päivä."
        },
        {
          "de": "Wir haben gestern lange ferngesehen.",
          "lv": "Katsoimme eilen pitkään televisiota."
        },
        {
          "de": "Er hat keine Lust fernzusehen.",
          "lv": "Häntä ei huvita katsoa televisiota."
        }
      ],
      "comparison": [
        {
          "word": "das Fernsehen",
          "meaning": "televisio",
          "example": "Das Fernsehen berichtet darüber. – Televisio uutisoi siitä."
        },
        {
          "word": "der Fernseher",
          "meaning": "televisio(vastaanotin)",
          "example": "Der Fernseher ist neu. – Televisio on uusi."
        },
        {
          "word": "ansehen",
          "meaning": "katsoa, katsella",
          "example": "Wir sehen einen Film an. – Katsomme elokuvan."
        }
      ],
      "tip": [
        "Muista: fern siirtyy lauseen loppuun — Ich sehe heute Abend fern.",
        "Perfektissä kaikki yhteen: ferngesehen."
      ],
      "important": [
        "Ei voi sanoa ”Ich fernsehe”: oikein on Ich sehe fern.",
        "Substantiivina (das Fernsehen) se tarkoittaa televisiota; verbinä — katsoa televisiota."
      ],
